// Generates packages/sdk/src/abi.ts from Foundry artifacts (run after `forge build`).
import { readFileSync, writeFileSync } from "node:fs";
const root = new URL("..", import.meta.url).pathname;
const pick = (file, name) => JSON.parse(readFileSync(`${root}contracts/out/${file}/${name}.json`, "utf8")).abi;
const out = [
  "// AUTO-GENERATED by scripts/gen-abi.mjs from contracts/out — do not edit.",
  `export const leashVaultAbi = ${JSON.stringify(pick("LeashVault.sol", "LeashVault"), null, 2)} as const;`,
  `export const leashFactoryAbi = ${JSON.stringify(pick("LeashFactory.sol", "LeashFactory"), null, 2)} as const;`,
  `export const pqVerifierAbi = ${JSON.stringify(pick("EthFalconVerifier.sol", "EthFalconVerifier"), null, 2)} as const;`,
  "",
].join("\n\n");
writeFileSync(`${root}packages/sdk/src/abi.ts`, out);
console.log("wrote packages/sdk/src/abi.ts");
